/** Saved selections refer to column names; column positions are only source metadata. */

/** @typedef {Record<string, string>} ColumnMapping */
/** @typedef {{version: number, headers: string[], mapping: ColumnMapping, headerRow: number}} ImportPreset */

function headerText(value) {
  return value == null ? '' : String(value).replace(/^\uFEFF/, '').trim();
}

function headerKey(value) {
  const text = headerText(value).normalize('NFKC');
  // These labels are generated by the importer from a column position. They
  // cannot identify the same column after a file has been edited.
  if (!text || /^未命名列\s*\d+$/u.test(text)) return '';
  return text.toLowerCase().replace(/\s+/gu, '');
}

function columnIndex(value, length) {
  if (value === '' || value == null) return null;
  const text = String(value).trim();
  if (!/^(0|[1-9]\d*)$/.test(text)) return null;
  const index = Number(text);
  return Number.isSafeInteger(index) && index < length ? index : null;
}

function indexHeaders(headers) {
  const result = new Map();
  headers.forEach((header, index) => {
    const key = headerKey(header);
    if (!key) return;
    if (!result.has(key)) result.set(key, []);
    result.get(key).push(index);
  });
  return result;
}

function isRecord(value) {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function isOrderMapping(mapping) {
  return isRecord(mapping) && Object.hasOwn(mapping, 'buyerUsername') && Object.hasOwn(mapping, 'creatorId') && Object.hasOwn(mapping, 'orderId');
}

function isBuyerHeader(value) {
  return ['buyerusername', '买家账号', '买家用户名'].includes(headerKey(value));
}

/**
 * Keep the original format readable by earlier workbench versions. Invalid
 * selected positions are saved as explicit blanks rather than stale indexes.
 * @param {unknown[]} headers
 * @param {Record<string, unknown>} mapping
 * @param {number} [headerRow]
 * @returns {ImportPreset}
 */
export function createImportPreset(headers, mapping, headerRow = 1) {
  const savedHeaders = Array.isArray(headers) ? headers.map(headerText) : [];
  /** @type {ColumnMapping} */
  const savedMapping = {};
  for (const [field, value] of Object.entries(isRecord(mapping) ? mapping : {})) {
    const index = columnIndex(value, savedHeaders.length);
    savedMapping[field] = index == null ? '' : String(index);
  }
  return {
    version: 1,
    ...(isOrderMapping(savedMapping) ? {orderCreatorIdentityVersion: 1} : {}),
    headers: savedHeaders,
    mapping: savedMapping,
    headerRow: Number.isSafeInteger(headerRow) && headerRow > 0 ? headerRow : 1,
  };
}

/**
 * Restore a confirmed mapping onto the CURRENT header row. Missing or
 * duplicated saved header names require a new choice; they never fall back to
 * an unrelated column at the old position. Only new/unconfigured fields use
 * automatic guesses. Explicit saved blanks continue to mean "do not import".
 *
 * Diagnostics contain canonical field keys so the UI can use its field labels.
 * This also works without a preset, validating automatic guesses for duplicate
 * headers. The caller should retain the newly detected/selected header row.
 *
 * @param {unknown[]} headers
 * @param {ColumnMapping} autoMapping
 * @param {unknown} [preset]
 * @returns {{mapping: ColumnMapping, hasPreset: boolean, applied: string[], unmapped: string[], missing: string[], ambiguous: string[]}}
 */
export function restoreImportPreset(headers, autoMapping, preset) {
  const currentHeaders = Array.isArray(headers) ? headers : [];
  const currentIndex = indexHeaders(currentHeaders);
  const fields = Object.keys(isRecord(autoMapping) ? autoMapping : {});
  /** @type {ColumnMapping} */
  const mapping = {};
  const applied = new Set(), unmapped = new Set(), missing = new Set(), ambiguous = new Set();

  for (const field of fields) {
    const index = columnIndex(autoMapping[field], currentHeaders.length);
    const key = index == null ? '' : headerKey(currentHeaders[index]);
    mapping[field] = index != null && key ? String(index) : '';
    if (key && currentIndex.get(key)?.length !== 1) {
      mapping[field] = '';
      ambiguous.add(field);
    }
  }

  const validPreset = isRecord(preset) && Array.isArray(preset.headers) && isRecord(preset.mapping);
  const savedMapping = validPreset ? preset.mapping : {};
  const hasPreset = validPreset && fields.some(field => Object.hasOwn(savedMapping, field));
  if (hasPreset) {
    const savedIndex = indexHeaders(preset.headers);
    for (const field of fields) {
      if (!Object.hasOwn(savedMapping, field)) continue;
      // A saved explicit decision replaces any automatic candidate/diagnostic.
      mapping[field] = '';
      ambiguous.delete(field);
      if (savedMapping[field] === '') {
        unmapped.add(field);
        continue;
      }
      const oldPosition = columnIndex(savedMapping[field], preset.headers.length);
      const key = oldPosition == null ? '' : headerKey(preset.headers[oldPosition]);
      const candidates = key ? currentIndex.get(key) || [] : [];
      if (!key || !candidates.length) {
        missing.add(field);
      } else if (savedIndex.get(key)?.length !== 1 || candidates.length !== 1) {
        ambiguous.add(field);
      } else {
        mapping[field] = String(candidates[0]);
        applied.add(field);
      }
    }

    // A manual choice takes precedence over a guess for another field. Two
    // deliberately saved choices may share a column, as the user selected it.
    const selectedColumns = new Set([...applied].map(field => mapping[field]));
    for (const field of fields) {
      const sharedBuyer = isOrderMapping(autoMapping) && field === 'buyerUsername' && mapping[field] === mapping.creatorId && isBuyerHeader(currentHeaders[Number(mapping[field])]);
      if (!sharedBuyer && !Object.hasOwn(savedMapping, field) && mapping[field] !== '' && selectedColumns.has(mapping[field])) {
        mapping[field] = '';
        ambiguous.add(field);
      }
    }
  }

  // Older All Orders presets either selected the affiliate Creator Handle or
  // explicitly left the recipient empty because Buyer Username was previously
  // blocked. Upgrade only that obsolete policy; other manual choices survive.
  // Newly saved presets carry the version flag, so an intentional new blank is
  // still respected. The source and recipient may deliberately share one column.
  if (hasPreset && isOrderMapping(autoMapping) && preset.orderCreatorIdentityVersion !== 1) {
    const buyerColumns = currentHeaders.map((header, index) => isBuyerHeader(header) ? index : -1).filter(index => index >= 0);
    const oldCreatorIndex = columnIndex(savedMapping.creatorId, preset.headers.length);
    const oldCreatorHeader = oldCreatorIndex == null ? '' : headerKey(preset.headers[oldCreatorIndex]);
    const obsoleteChoice = savedMapping.creatorId === '' || !Object.hasOwn(savedMapping, 'creatorId') || oldCreatorHeader === 'creatorhandle' || isBuyerHeader(oldCreatorHeader);
    if (buyerColumns.length === 1) {
      for (const field of obsoleteChoice ? ['creatorId', 'buyerUsername'] : ['buyerUsername']) {
        mapping[field] = String(buyerColumns[0]);
        applied.add(field); unmapped.delete(field); missing.delete(field); ambiguous.delete(field);
      }
    } else if (obsoleteChoice) {
      // An old attribution selection cannot become a new manual recipient
      // merely because Buyer is missing or ambiguous in the replacement file.
      mapping.creatorId = '';
      applied.delete('creatorId'); unmapped.delete('creatorId');
      if (buyerColumns.length > 1) { ambiguous.add('creatorId'); missing.delete('creatorId'); }
      else { missing.add('creatorId'); ambiguous.delete('creatorId'); }
    }
    if (obsoleteChoice && !Object.hasOwn(savedMapping, 'attributedCreatorId')) {
      const attributionIndex = columnIndex(autoMapping.attributedCreatorId, currentHeaders.length);
      const attributionKey = attributionIndex == null ? '' : headerKey(currentHeaders[attributionIndex]);
      if (attributionKey && currentIndex.get(attributionKey)?.length === 1) {
        mapping.attributedCreatorId = String(attributionIndex);
        ambiguous.delete('attributedCreatorId');
      }
    }
  }

  return {
    mapping,
    hasPreset: !!hasPreset,
    applied: [...applied],
    unmapped: [...unmapped],
    missing: [...missing],
    ambiguous: [...ambiguous],
  };
}
